const body = $json.body ?? $json;
const now = new Date().toISOString();
return [{
  json: {
    tenant_id: 'peskids',
    name: (body.full_name || body.name || '').trim() || 'Unknown',
    email: (body.email || '').trim().toLowerCase() || null,
    phone: body.phone?.trim() || null,
    class_modality: body.class_modality || null,
    neighborhood: body.neighborhood?.trim() || null,
    grade_interested: body.grade_interested || null,
    referral_source: body.referral_source?.trim() || null,
    referral_code: body.referral_code?.trim()?.toUpperCase() || null,
    referred_by_code: body.referred_by_code?.trim()?.toUpperCase() || null,
    referral_discount_cents: 0,
    referral_redemptions: 0,
    status: 'new',
    received_at: now
  }
}];
